style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.pinimg.com/originals/48/7f/ba/487fba023be0ab6a6a0c23b05d01a493.jpg") no-repeat center center fixed;
        background-size: cover;
    }
    
   
    .container, .content, .game-list, .header, .footer {
        background: transparent !important;
    }
    
    
    .btn-primary, .btn-secondary, .game-card, .nav-menu {
        background-color: #f5c6e6 !important;
        border-color: #f5c6e6 !important;
        color: #ffffff !important;
    }
    
    
    .game-card, .navbar, .profile-card, .settings-panel {
        background: rgba(245, 198, 230, 0.2) !important;
    }
}
